/* Lot 7 : référentiels (missions, symbologie et calques, commandement et géométrie), rubrique « Référentiels » hors cycle MEDOT
   (chargé après soutien.js). Modules ms_* (7a), sy_* (7b), cd_* (7c) ; examen « rf ». Insérés via FX_MODS (avant « Outils »),
   encarts dans le cycle via FX_ENC, sigles via FX_LEX. */
const RF_GRP="Référentiels";
const MS_GTIA=["Boucler","Brécher","Contrôler","Couvrir","Défendre","Détruire","Donner un coup d’arrêt","Éclairer","Effectuer un raid","Exploiter","Fixer","Flanc-garder","Freiner","Harceler","Infiltrer","Interdire","Jalonner","Mener un combat d’usure","Neutraliser","Ratisser","Reconnaître","Recueillir","Réduire une résistance","Relever","S’emparer de","Surveiller"];
const MS_MODS=[
{id:"ms_cadre",grp:RF_GRP,title:"Modes tactiques, MAG et missions",qtag:"Missions",
 but:"Distinguer mode tactique, mode d’action générique (MAG), mission et tâche, savoir ce que chaque niveau reçoit et quels MAG une brigade peut adopter selon son type, pour analyser correctement la mission reçue et formuler celles des subordonnés.",
 sections:[
 {h:"Définitions",l:["Mode tactique : action générique caractérisant un type d’action des forces terrestres selon la nature des effets à produire sur les forces ou le milieu : mode offensif, mode défensif, sécurisation, assistance.","Mode d’action générique (MAG) : façon d’agir dominante, issue des modes tactiques, à un niveau de commandement donné (niveaux 1 à 3). Il permet de choisir les moyens nécessaires et de combiner leurs actions pour produire un effet sur l’ennemi ou le milieu.","Mission : expression claire et concise de l’action à accomplir et du but poursuivi.","Tâche : ce qui doit être accompli pour que la mission soit exécutée ; elle est le plus souvent une partie de l’action, rarement toute l’action. Elle implique des moyens et des procédés spécifiques (déplacement, franchissement, débouché, recueil…). Les tâches peuvent être simultanées ou successives.","Tâches spécifiées : explicitement notifiées dans les ordres de l’échelon supérieur (directive, OPLAN, PS, OPORD, FRAGO…). Tâches induites : non notifiées, mais déduites de l’analyse de la mission reçue.","Effet : changement d’état ou d’attitude, résultat physique ou immatériel, conséquence d’actions militaires ou non visant une cible ou un objectif particulier."]},
 {h:"MAG ou mission : qui reçoit quoi ?",l:["Les niveaux 1 à 3 (corps d’armée, division, brigade) reçoivent des MAG et non des missions. Un MAG prend en compte toutes les fonctions opérationnelles et reste assez souple pour laisser à ces commandements une liberté d’interprétation en conception et en conduite.","Les niveaux 4 et inférieurs (GTIA et en dessous) reçoivent des missions. Une mission est strictement définie, intègre tâches et composantes, et limite la liberté d’interprétation de ces échelons.","Raison de cette distinction : aux niveaux 1 à 3, on conçoit une manœuvre dans toutes ses composantes ; aux niveaux subordonnés, la manœuvre est exécutée."]},
 {h:"Missions de la division",l:["Mode tactique offensif : marcher à l’ennemi, attaquer, conquérir une zone, exploiter.","Mode tactique défensif : défendre ferme, défendre une zone, mener une défense d’usure.","Mode tactique de sécurisation : sécuriser une zone."]},
 {h:"Concordance des missions du niveau 1 au niveau 3",tb:{cols:["Mode et phase","Corps d’armée","Division","Brigade"],rows:[
  ["Offensif – phase préliminaire","Marcher à l’ennemi","Marcher à l’ennemi","Mener une reconnaissance offensive"],
  ["Offensif – phase de conduite","Attaquer","Attaquer ; conquérir une zone","Attaquer ; conquérir une zone ; percer ; combattre sur les arrières ; soutenir (de même en défensif)"],
  ["Offensif – phase d’exploitation","Exploiter","Exploiter","Exploiter ; mener un raid"],
  ["Défensif – phase de conduite","Mener une manœuvre retardatrice ; défendre une zone","Défendre ferme ; défendre une zone ; mener une défense d’usure","Défendre ferme ; défendre une zone ; mener une défense d’usure ; couvrir ; combattre sur les arrières ; contre-attaquer"],
  ["Sécurisation","Sécuriser une zone","Sécuriser une zone","Contrôler une zone ; boucler"]]},
  l:["En mode défensif, la phase préliminaire peut relever d’un autre mode tactique ; la phase d’exploitation correspond à la bascule vers un autre mode tactique."]},
 {h:"MAG de la brigade selon son type",tb:{cols:["Mode d’action générique","BIA blindée","BIA légère blindée","BIA motorisée"],rows:[
  ["Offensif : reconnaissance offensive","✓","✓","✓"],["Offensif : attaque","✓","✓","✓"],["Offensif : conquête de zone","✓","✓","✓"],["Offensif : raid","✓","✓","✓"],["Offensif : exploitation","✓","✓","–"],["Offensif : percée","✓","✓","–"],["Offensif : combat sur les arrières","–","–","✓"],
  ["Défensif : défense de zone","✓","✓","✓"],["Défensif : défense ferme","✓","–","–"],["Défensif : défense d’usure","✓","✓","✓"],["Défensif : couverture","✓","✓","✓"],
  ["Sécurisation : contrôle de zone","✓","✓","✓"],["Sécurisation : contre-rébellion","–","✓","✓"],["Sécurisation : interposition","–","✓","✓"],["Sécurisation : évacuation de population menacée","–","✓","✓"],["Sécurisation : sécurisation de zone","–","✓","✓"]]},
  l:["Seule la BIA blindée peut défendre ferme ; seule la BIA motorisée combat sur les arrières ; exploitation et percée ne sont pas des MAG de la BIA motorisée ; la BIA blindée n’adopte pas les MAG de sécurisation autres que le contrôle de zone."]},
 {h:"Gabarits d’engagement de la brigade selon le nombre de GTIA",tb:{cols:["MAG","3 GTIA (front / profondeur)","4 GTIA (front / profondeur)","5 GTIA (front / profondeur)"],rows:[
  ["Reconnaissance offensive","20-30 km / 60 km","20-40 km / 70 km","20-60 km / 80 km"],["Attaque","10-25 km / 20 km","30-35 km / 35 km","30-40 km / 35 km"],["Conquête de zone","10-25 km / 50 km","20-35 km / 60 km","30-50 km / 70 km"],["Raid","10-25 km / 50 km","20-35 km / 60 km","30-50 km / 70 km"],["Exploitation","10-25 km / 60 km","20-35 km / 70 km","30-50 km / 80 km"],["Percée","10-25 km / 60 km","20-35 km / 70 km","30-50 km / 70 km"],
  ["Défense ferme","10-25 km / 50 km","15-30 km / 55 km","20-35 km / 60 km"],["Défense d’usure","10-30 km / 80 km","20-35 km / 60 km","30-50 km / 70 km"],["Défense de zone","10-20 km / 50 km","15-25 km / 70 km","20-30 km / 80 km"],["Couverture","25-50 km / 40 km","35-60 km / 50 km","45-70 km / 60 km"]]},
  l:["Ordres de grandeur pour dimensionner les MA ; les vitesses, délais et zones d’action par MAG figurent dans « Normes et délais »."],go:["normes"]},
 {h:"Capteurs et aérocombat selon le MAG",l:["Quel que soit le MAG, l’EEI ou le SGRC (échelon de découverte) ne conduit plus d’action cinétique : il surveille, éclaire ou jalonne. En exploitation, il peut aussi éclairer, reconnaître ou flanc-garder pendant la préparation.","Le SGAM HRA reconnaît, précise le dispositif ennemi et, selon le MAG, attaque, neutralise, détruit, appuie un GTIA, couvre l’action principale sur un délai court ; en défensive, il jalonne, freine, mène un coup d’arrêt sur l’échelon 1 ennemi ou contre-attaque sur l’échelon 2.","Le SGAM HMA héliporte des forces pour saisir des points du terrain ou préfigurer une couverture, mène un RAID ART, héliporte un DHIG (contre-mobilité en amont de l’arrivée de l’ennemi) ou met en place un élément réservé."],go:["al_man","rn_cap"]}],
 vig:["Brigade et division reçoivent un MAG, le GTIA une mission : ne pas confondre les registres.","Lister les tâches spécifiées, puis déduire les tâches induites.","Vérifier que le MAG envisagé est permis pour le type de BIA.","Dimensionner le MA avec les gabarits selon le nombre de GTIA."],
 apply:[{t:"note",x:"Pour ta mission : nomme le MAG reçu et le mode tactique dont il relève ; liste les tâches spécifiées, puis les tâches induites que tu en déduis ; vérifie que le MAG est permis pour ton type de BIA et compare ta zone aux gabarits."},
  {t:"table",id:"mscadre",l:"Tâches de ma mission",cols:[{k:"t",l:"Tâche"},{k:"n",l:"Nature",o:["Spécifiée","Induite"]},{k:"s",l:"Source ou raisonnement"},{k:"u",l:"Unité ou fonction concernée",s:1}]},
  {t:"doc",l:"Tâches de ma mission"}],
 quiz:[
 {q:"Quels niveaux de commandement reçoivent des modes d’action génériques (MAG) plutôt que des missions ?",o:["Les niveaux 1 à 3","Les niveaux 4 et inférieurs","Le seul niveau 1","Tous les niveaux"],a:0,e:"Corps d’armée, division et brigade reçoivent des MAG ; les niveaux 4 et inférieurs, des missions."},
 {q:"Qu’est-ce qui caractérise une mission par rapport à un MAG ?",o:["Elle est strictement définie et limite la liberté d’interprétation","Elle prend en compte toutes les fonctions opérationnelles","Elle laisse une liberté d’interprétation en conception","Elle n’a pas de but"],a:0,e:"Le MAG est souple et laisse la liberté d’interprétation en conception et en conduite."},
 {q:"Pourquoi distingue-t-on MAG et mission ?",o:["Aux niveaux 1 à 3 on conçoit la manœuvre ; aux niveaux subordonnés on l’exécute","Pour des raisons de traduction OTAN","Parce que les MAG sont réservés aux opérations de sécurisation","Parce que la mission n’a pas d’effet à produire"],a:0,e:"Conception de la manœuvre dans toutes ses composantes en haut ; exécution en bas."},
 {q:"Lequel n’est PAS un mode tactique ?",o:["Le mode de reconnaissance","Le mode offensif","La sécurisation","L’assistance"],a:0,e:"Quatre modes tactiques : offensif, défensif, sécurisation, assistance."},
 {q:"Comment appelle-t-on une tâche non notifiée dans les ordres reçus mais déduite de l’analyse de la mission ?",o:["Une tâche induite","Une tâche spécifiée","Une contrainte","Un impératif"],a:0,e:"Les tâches spécifiées sont explicitement notifiées dans les ordres de l’échelon supérieur."},
 {q:"En mode offensif, quelle est la mission de phase préliminaire de la brigade, en concordance avec la marche à l’ennemi de la division ?",o:["Mener une reconnaissance offensive","Mener une attaque coordonnée","Mener une exploitation en profondeur","Mener une couverture mobile"],a:0,e:"Corps d’armée et division marchent à l’ennemi ; la brigade mène une reconnaissance offensive."},
 {q:"Laquelle de ces missions est propre au niveau brigade dans la concordance (absente aux niveaux division et corps) ?",o:["Percer","Attaquer","Exploiter","Défendre une zone"],a:0,e:"Percer, combattre sur les arrières, soutenir, couvrir, contre-attaquer, boucler n’apparaissent qu’au niveau brigade."},
 {q:"En mode défensif, quelle mission figure au niveau corps d’armée mais pas aux niveaux inférieurs ?",o:["Mener une manœuvre retardatrice","Défendre ferme","Mener une défense d’usure","Couvrir"],a:0,e:"Le corps d’armée mène une manœuvre retardatrice ou défend une zone."},
 {q:"En sécurisation, quelles missions correspondent au niveau brigade ?",o:["Contrôler une zone, boucler","Sécuriser une zone uniquement","Interdire, harceler","Défendre ferme"],a:0,e:"Corps d’armée et division sécurisent une zone."},
 {q:"Quel type de BIA est le seul à pouvoir adopter la défense ferme ?",o:["La BIA blindée","La BIA légère blindée","La BIA motorisée","Les trois"],a:0,e:"Défense de zone, défense d’usure et couverture sont communes aux trois types."},
 {q:"Quel MAG est propre à la BIA motorisée ?",o:["Le combat sur les arrières","La percée","L’exploitation","La défense ferme"],a:0,e:"Exploitation et percée ne figurent pas parmi ses MAG."},
 {q:"Quels MAG de sécurisation la BIA blindée peut-elle adopter ?",o:["Le contrôle de zone seulement","Tous","Aucun","L’interposition et la contre-rébellion"],a:0,e:"Contre-rébellion, interposition, évacuation de population menacée et sécurisation de zone relèvent des BIA légère blindée et motorisée."},
 {q:"Avec 3 GTIA, quel gabarit d’engagement pour une attaque de brigade ?",o:["10 à 25 km de front, 20 km de profondeur","20 à 30 km de front, 60 km de profondeur","25 à 50 km de front, 40 km de profondeur","30 à 40 km de front, 35 km de profondeur"],a:0,e:"30 à 40 km de front et 35 km de profondeur correspondent à 5 GTIA."},
 {q:"Quel MAG défensif de la brigade présente le front le plus large ?",o:["La couverture","La défense ferme","La défense de zone","La défense d’usure"],a:0,e:"Couverture : 25 à 50 km de front avec 3 GTIA, jusqu’à 45 à 70 km avec 5 GTIA."},
 {q:"Quel que soit le MAG, que peut encore faire l’échelon de découverte (EEI ou SGRC) une fois le contact pris ?",o:["Surveiller, éclairer, jalonner","Attaquer et détruire","Défendre ferme","Rien"],a:0,e:"Il n’est plus en capacité d’avoir une action cinétique."}]},
{id:"ms_divbia",grp:RF_GRP,title:"Missions de niveau division et brigade",qtag:"Missions",
 but:"Connaître la définition française, et le cas échéant OTAN, des missions de niveau division et brigade, pour employer le mot juste dans l’analyse de la mission et dans les ordres.",
 sections:[
 {h:"Missions de niveau division",l:["Attaquer (to attack) – FR : détruire un adversaire ou le chasser des zones qu’il occupe. OTAN : mener une action offensive contre un objectif désigné.","Attaque en force : le chef applique sur l’adversaire la totalité des feux dont il dispose et profite de leurs effets pour faire progresser ses éléments directement sur leurs objectifs.","Attaque en souplesse : la prédominance est donnée à l’infiltration, suivie d’attaques locales sur des objectifs débordés ou dépassés.","Conquête de zone (to conquer) : soustraire une zone ou un objectif terrain (zone refuge, sanctuaire…) à un ennemi installé, pour s’en emparer puis la contrôler.","Défendre ferme (point, secteur, zone) (to defend) : interdire à l’ennemi de franchir une ligne ou de s’emparer d’une zone.","Défense de zone (to defend) : préserver le terrain en y absorbant l’ennemi dans une série de positions entrecroisées d’où il peut être en grande partie détruit par le feu ; sa destruction complète n’est pas systématiquement recherchée ; elle conjugue réserves mobiles et positions défensives.","Défense d’usure : détruire progressivement dans la profondeur les pénétrations ennemies en se laissant dépasser le cas échéant.","Marche à l’ennemi (advance to contact) – FR : MAG de niveau division visant à prendre le contact avec un dispositif de marche qui permet de manœuvrer d’emblée et de conserver l’initiative dans la foulée du premier contact. OTAN : manœuvre offensive pour établir ou rétablir le contact avec l’ennemi."]},
 {h:"Missions de niveau brigade : offensive",l:["Attaquer (to attack) : mêmes définitions qu’au niveau division, en force ou en souplesse.","Conquête de zone (to seize, valeur à confirmer) : soustraire une zone ou un objectif terrain (zone refuge…) à un adversaire installé.","Effectuer un raid (to raid) : incursion rapide et profonde à l’intérieur d’un dispositif ennemi pour s’emparer d’une zone clé ou détruire un objectif de grand intérêt opérationnel.","Exploiter (to exploit) – FR : après rupture ou submersion du dispositif adverse, poursuivre dans la profondeur sa désorganisation et, si possible, sa destruction. OTAN : tirer le meilleur parti d’un succès ou d’opportunités et exploiter les gains initiaux.","Percer (to penetrate) : mode d’action consistant à mener une attaque suivie d’une exploitation par la BIA.","Reconnaître (to recce) : la reconnaissance offensive est un MAG destiné à neutraliser les éléments de sûreté adverses et à préciser le dispositif qu’ils couvrent, afin d’en préparer l’attaque."]},
 {h:"Missions de niveau brigade : défensive et sécurisation",l:["Couvrir (to cover) : ensemble des mesures actives ou passives prises pour s’opposer à une action éventuelle de l’ennemi pouvant menacer le déroulement de l’action principale amie.","Défendre ferme (to defend) : forme de la manœuvre d’arrêt qui vise à empêcher l’ennemi de franchir une ligne du terrain ou de s’emparer d’un secteur.","Défense d’usure : forme de la manœuvre d’arrêt visant à détruire progressivement, dans la profondeur d’une zone, les pénétrations ennemies en se laissant dépasser le cas échéant.","Défense de zone : préservation du terrain par l’absorption de l’ennemi dans des positions entrecroisées, en conjuguant réserves mobiles et positions défensives, afin de ralentir et souvent canaliser sa progression, de l’affaiblir en lui infligeant des pertes tout en préservant au mieux le terrain, et de préparer une reprise de l’offensive par l’engagement de forces initialement réservées.","Contrôler (zone, itinéraire, secteur, point clé) (to control) – FR : se déployer sur un secteur, une position ou un trait caractéristique du terrain, avec ou sans usage de la force, pour en assurer la libre disposition, déceler et neutraliser toute présence suspecte à ses abords et éviter sa destruction ou sa prise. Le secteur est une partie de la zone donnée en compte à l’échelon supérieur. OTAN : créer et maintenir une influence physique ou psychologique sur un processus, des individus, une organisation, des infrastructures et services essentiels ou le terrain."]},
 {h:"À ne pas confondre",l:["Défendre ferme : on tient une ligne ou une zone. Défense d’usure : on détruit progressivement en se laissant dépasser. Défense de zone : on préserve le terrain en absorbant l’ennemi, sans rechercher systématiquement sa destruction complète.","Attaque en force : les feux d’abord, puis la progression directe. Attaque en souplesse : l’infiltration d’abord, puis des attaques locales.","Percer = attaquer puis exploiter ; exploiter suppose une rupture ou une submersion préalable du dispositif adverse."]}],
 vig:["Employer le verbe défini, jamais un synonyme approximatif.","En défensive, choisir entre tenir (défendre ferme), user (défense d’usure) ou absorber (défense de zone).","Préciser en force ou en souplesse pour une attaque."],
 quiz:[
 {q:"Quelle attaque donne la prédominance à l’infiltration, suivie d’attaques locales sur des objectifs débordés ?",o:["L’attaque en souplesse","L’attaque en force","Le raid","La percée"],a:0,e:"En force, le chef applique d’abord la totalité de ses feux puis progresse directement sur les objectifs."},
 {q:"Quelle mission vise à interdire à l’ennemi de franchir une ligne ou de s’emparer d’une zone ?",o:["Défendre ferme","Défense d’usure","Couvrir","Freiner"],a:0,e:"Au niveau brigade, c’est une forme de la manœuvre d’arrêt."},
 {q:"Quelle mission consiste à détruire progressivement dans la profondeur les pénétrations ennemies en se laissant dépasser ?",o:["La défense d’usure","La défense de zone","Défendre ferme","Jalonner"],a:0,e:"La défense de zone, elle, préserve le terrain en absorbant l’ennemi."},
 {q:"Dans la défense de zone, la destruction complète de l’ennemi est-elle recherchée ?",o:["Pas systématiquement","Toujours","Jamais, seul le terrain compte","Uniquement par l’aérocombat"],a:0,e:"Elle vise à ralentir et canaliser l’ennemi, l’affaiblir et préparer la reprise de l’offensive."},
 {q:"Que conjugue la défense de zone ?",o:["Réserves mobiles et positions défensives","Raids blindés et infiltrations en profondeur","Obstacles continus et feux indirects massifs","Positions de freinage et recueils successifs"],a:0,e:"Positions entrecroisées et forces initialement réservées pour reprendre l’offensive."},
 {q:"Quelle est la définition OTAN de « marche à l’ennemi » ?",o:["Manœuvre offensive pour établir ou rétablir le contact","Mouvement sans contact vers une zone de regroupement","Attaque d’un objectif désigné","Poursuite d’un ennemi qui se replie"],a:0,e:"En France, c’est un MAG de niveau division."},
 {q:"Selon la définition française, que suppose l’exploitation ?",o:["Une rupture ou une submersion préalable du dispositif adverse","Un ennemi intact, que l’on cherche à fixer dans la profondeur","Une phase défensive préalable ayant usé l’attaque adverse","L’emploi exclusif de l’aérocombat et des feux dans la profondeur"],a:0,e:"Elle poursuit dans la profondeur la désorganisation de l’adversaire et, si possible, sa destruction."},
 {q:"Comment la percée est-elle définie au niveau brigade ?",o:["Une attaque suivie d’une exploitation par la BIA","Une infiltration suivie d’un raid par la BIA","Une reconnaissance offensive suivie d’une attaque","Une attaque suivie d’une défense de zone par la BIA"],a:0,e:"Percer combine deux temps : attaquer, puis exploiter."},
 {q:"Quel est l’objet de la reconnaissance offensive ?",o:["Neutraliser les éléments de sûreté adverses et préciser le dispositif qu’ils couvrent","Détruire le gros de l’ennemi et s’emparer des points clés qu’il tient dans la profondeur","Tenir une ligne face à l’ennemi pour permettre le déploiement des gros de la division","S’emparer d’une zone clé dans la profondeur avant l’arrivée des réserves adverses"],a:0,e:"Elle prépare l’attaque."},
 {q:"Qu’est-ce que le raid au niveau brigade ?",o:["Une incursion rapide et profonde dans le dispositif ennemi pour saisir une zone clé ou détruire un objectif de grand intérêt","Une attaque frontale en force pour rompre le dispositif ennemi puis tenir durablement le terrain conquis face aux réserves","Une couverture mobile menée dans la profondeur pour protéger le flanc de la division contre une contre-attaque adverse","Un contrôle de zone mené sur les arrières de la division pour y neutraliser les éléments infiltrés et sécuriser les axes"],a:0,e:"Il ne vise pas la tenue durable du terrain."},
 {q:"Que désigne « couvrir » au niveau brigade ?",o:["Les mesures actives ou passives contre une action ennemie menaçant l’action principale amie","La protection rapprochée d’un convoi logistique sur un itinéraire exposé aux actions adverses","La défense ferme d’un point clé dont la perte compromettrait la manœuvre de la division","Le camouflage et la dispersion des PC et des moyens d’appui contre les frappes adverses"],a:0,e:"La couverture protège le déroulement de l’action principale."},
 {q:"Contrôler une zone se fait…",o:["avec ou sans usage de la force","toujours par la force","sans jamais employer la force","uniquement par des feux"],a:0,e:"Il s’agit d’assurer la libre disposition de l’espace et d’y déceler et neutraliser toute présence suspecte."}]},
{id:"ms_gt1",grp:RF_GRP,title:"Missions de niveau GTIA (de Boucler à Freiner)",qtag:"Missions",
 but:"Connaître la définition exacte des missions données aux GTIA, pour analyser une mission reçue et rédiger sans ambiguïté celles des subordonnés.",
 sections:[
 {h:"De Boucler à Détruire",l:["Boucler (to cordon off) : isoler, par un dispositif continu établi le long d’une ligne définie, une portion de terrain pour interdire ou au minimum signaler tout franchissement de cette ligne par l’ennemi.","Brécher (to break through) : forcer et/ou sécuriser un passage au travers d’une défense ennemie.","Contrôler (zone, itinéraire, secteur, point clé) (to control) : mêmes définitions qu’au niveau brigade, française et OTAN.","Couvrir (to cover) – FR : prendre l’ensemble des mesures actives ou passives pour renseigner et s’opposer par le feu et le mouvement à une action éventuelle de l’adversaire pouvant menacer l’action principale amie. OTAN : assurer la sécurité d’une force principale en se battant tout en observant et en transmettant des informations ; une force de couverture peut manœuvrer indépendamment de la force principale.","Défendre (point, secteur, zone) (to defend) : 1. interdire à l’ennemi de franchir une ligne ou de s’emparer d’une zone, en tenant sans esprit de recul ; 2. détruire progressivement dans la profondeur les pénétrations ennemies sur une direction ou dans une zone, par des détachements mobiles, des feux et des obstacles, en se laissant dépasser le cas échéant.","Détruire (to destroy) : mettre définitivement hors d’usage ou hors de combat un objectif ou une force ennemie."]},
 {h:"De Donner un coup d’arrêt à Exploiter",l:["Donner un coup d’arrêt (to conduct a blocking action) – FR : déclencher par surprise une action à base de feux sur une formation ennemie en mouvement offensif pour briser son élan et lui imposer un arrêt, en lui infligeant le maximum de pertes ; un coup d’arrêt est par essence temporaire. OTAN : interdire l’accès à un secteur ou empêcher une progression dans une direction.","Éclairer (to screen) : rechercher le renseignement sans engager le combat, pour contribuer à la sûreté rapprochée du chef et de la troupe.","Effectuer un raid (to raid) : incursion rapide et profonde dans un dispositif ennemi pour saisir une zone clé, détruire des objectifs de grand intérêt opérationnel ou exécuter un acte particulier (délivrance de prisonniers, évacuation de ressortissants, capture d’une catégorie de personnes…). Pour la cavalerie, « mener un raid blindé » est un procédé particulier.","Exploiter (to exploit) : mêmes définitions qu’au niveau brigade, française et OTAN."]},
 {h:"De Fixer à Freiner",l:["Fixer (to fix) – FR : exercer sur l’ennemi une pression suffisante pour lui interdire tout mouvement ou redéploiement. OTAN : empêcher tout ou partie d’une force hostile, d’une population, d’un groupe ou d’une organisation de quitter un emplacement défini pendant une période donnée.","Flanc-garder (to flankguard) : assurer une sûreté latérale, fixe ou mobile, au profit de l’élément principal ; renseigner et couvrir la formation considérée et éventuellement assurer la liaison avec les unités voisines.","Freiner (to delay) – FR : ralentir la progression ennemie sur une direction ou dans une zone par des détachements mobiles, des feux et des obstacles. OTAN : gagner du temps en cédant du terrain, en ralentissant le rythme adverse et en lui causant le plus de dégâts possible, en évitant si possible un engagement décisif."]}],
 vig:["Éclairer, c’est renseigner sans combattre ; reconnaître, c’est renseigner en combattant éventuellement.","Le coup d’arrêt est temporaire ; défendre ferme se fait sans esprit de recul.","Détruire est définitif ; neutraliser est temporaire.","Fixer interdit tout mouvement ; freiner ralentit."],
 apply:[{t:"note",x:"Rédige les missions de tes subordonnés avec un verbe défini, un effet sur l’ennemi ou le terrain, une zone ou une direction et un délai."},
  {t:"table",id:"msgt",l:"Missions des subordonnés",cols:[{k:"u",l:"Unité"},{k:"m",l:"Mission",o:MS_GTIA},{k:"o",l:"Sur quoi (ennemi, terrain)"},{k:"z",l:"Zone, direction ou ligne"},{k:"h",l:"Délai ou durée"},{k:"b",l:"Afin de (but)",s:1}]},
  {t:"doc",l:"Missions des subordonnés"}],
 quiz:[
 {q:"Quelle mission isole une portion de terrain par un dispositif continu le long d’une ligne, pour interdire ou au moins signaler tout franchissement ?",o:["Boucler","Barrer","Interdire","Contrôler"],a:0,e:"Boucler (to cordon off)."},
 {q:"Quelle mission consiste à forcer et/ou sécuriser un passage au travers d’une défense ennemie ?",o:["Brécher","Percer","Contourner","Infiltrer"],a:0,e:"Brécher (to break through)."},
 {q:"Quelle différence entre éclairer et reconnaître ?",o:["Éclairer, c’est renseigner sans engager le combat ; reconnaître peut conduire à l’engager","Reconnaître, c’est renseigner sans engager le combat ; éclairer peut conduire à l’engager","Éclairer engage toujours le combat ; reconnaître se limite à l’observation du terrain","Aucune : ce sont deux synonymes, l’un employé par l’OTAN, l’autre par la doctrine française"],a:0,e:"Éclairer contribue à la sûreté rapprochée du chef et de la troupe."},
 {q:"Un coup d’arrêt est par essence…",o:["temporaire","définitif","défensif ferme sans esprit de recul","une action d’infiltration"],a:0,e:"Il brise l’élan d’une formation en mouvement offensif par une action surprise à base de feux."},
 {q:"Sur quel ennemi déclenche-t-on un coup d’arrêt ?",o:["Une formation en mouvement offensif","Un ennemi installé en défense","Des éléments infiltrés","Un ennemi en repli"],a:0,e:"Il lui impose un arrêt en lui infligeant le maximum de pertes."},
 {q:"Quelle mission exerce sur l’ennemi une pression suffisante pour lui interdire tout mouvement ou redéploiement ?",o:["Fixer","Freiner","Harceler","Neutraliser"],a:0,e:"Fixer (to fix)."},
 {q:"Selon l’OTAN, « freiner » (to delay) consiste à…",o:["gagner du temps en cédant du terrain sans s’engager de manière décisive","tenir une ligne sans recul jusqu’à l’arrivée de la force de contre-attaque","détruire l’ennemi dans la profondeur par des feux et des obstacles successifs","gagner du temps en tenant le terrain jusqu’à s’engager de manière décisive"],a:0,e:"En France : ralentir la progression ennemie par des détachements mobiles, des feux et des obstacles."},
 {q:"Que signifie « détruire » ?",o:["Mettre définitivement hors d’usage ou hors de combat","Mettre temporairement hors d’état d’agir","Chasser d’une zone","Empêcher l’accès à une zone"],a:0,e:"Neutraliser est temporaire."},
 {q:"Selon l’OTAN, une force de couverture…",o:["peut manœuvrer indépendamment de la force principale","reste toujours au contact direct de la force principale","observe et rend compte, sans jamais engager le combat","ne manœuvre que sur ordre de la force principale"],a:0,e:"Elle assure la sécurité de la force principale en se battant tout en observant et en transmettant des informations."},
 {q:"Flanc-garder, c’est assurer une sûreté…",o:["latérale, fixe ou mobile","dans la profondeur uniquement","sur les arrières uniquement","aérienne"],a:0,e:"En assurant éventuellement la liaison avec les unités voisines."},
 {q:"Pour la cavalerie, « mener un raid blindé » est…",o:["un procédé particulier","une mission de niveau division","synonyme de percer","une mission défensive"],a:0,e:"Le raid vise une zone clé, des objectifs de grand intérêt ou un acte particulier."},
 {q:"Défendre, dans son premier sens, implique de tenir…",o:["sans esprit de recul","en se laissant dépasser","seulement de nuit","pendant un délai fixé de 2 h"],a:0,e:"Le second sens détruit progressivement dans la profondeur en se laissant dépasser."}]},
{id:"ms_gt2",grp:RF_GRP,title:"Missions de niveau GTIA (de Harceler à Surveiller)",qtag:"Missions",
 but:"Connaître la définition exacte des autres missions données aux GTIA et les nuances qui les séparent.",
 sections:[
 {h:"De Harceler à Jalonner",l:["Harceler (to harass) : restreindre l’activité ennemie dans une zone ou sur un itinéraire et créer un climat d’insécurité, par le feu, des coups de main, des embuscades et des obstacles battus ou non.","Infiltrer (to infiltrate) – FR : introduire, si possible en secret, un volume de forces dans le dispositif ennemi en vue d’une action déterminée. OTAN : déplacer des éléments individuels ou de petits groupes d’un environnement non hostile vers un environnement hostile sans être détectés.","Interdire (to deny) – FR : empêcher l’ennemi d’accéder à une portion de terrain, de franchir une ligne ou d’utiliser du personnel ou une installation. OTAN : empêcher l’utilisation d’un espace, de personnel ou d’infrastructures par des mesures physiques ou psychologiques.","Jalonner (to conduct a retrograde screening action) : renseigner en permanence sur la progression d’un adversaire en maintenant devant lui des éléments mobiles qui, sans se laisser identifier ni accrocher, saisissent toute occasion de préciser le renseignement et de lui causer des pertes."]},
 {h:"De Mener un combat d’usure à Réduire une résistance",l:["Mener un combat d’usure (GTIA d’infanterie) : détruire progressivement dans la profondeur les pénétrations ennemies en se laissant dépasser le cas échéant.","Neutraliser (to neutralize) – FR : mettre l’adversaire hors d’état d’agir efficacement pendant un temps et dans une zone donnés. OTAN : mettre un élément ennemi temporairement hors d’état d’entraver une opération amie.","Ratisser (to search) : rechercher sur un emplacement, un secteur ou une zone toutes les forces ennemies qui s’y trouvent, ou tous équipements, caches ou moyens de subsistance adverses.","Reconnaître (to recce) : aller chercher le renseignement tactique ou technique, sur le terrain ou l’ennemi, sur un point ou dans une zone, en engageant éventuellement le combat ; on reconnaît un point, une zone, un itinéraire, un axe ou une direction.","Recueillir (pas de symbole) : soutenir, à partir d’une zone ou d’une ligne, une unité qui se replie, lui permettre de franchir son propre dispositif, puis la couvrir pendant un certain délai.","Réduire une résistance (to reduce a resistance) : mettre hors de combat un élément ennemi après l’avoir repéré, identifié et localisé ; détruire les reliquats localisés et fixés d’une formation ennemie déjà amoindrie."]},
 {h:"De Relever à Surveiller",l:["Relever (to relieve, pas de symbole) : procédé d’exécution consistant à remplacer une force par une autre, en général de mêmes capacités, sur position, par dépassement ou par recueil ; l’unité relevante prend à sa charge tout ou partie des responsabilités de mission et de zone de l’unité relevée.","Relève sur position (relief in place, OTAN) : sur ordre de l’autorité supérieure, tout ou partie d’une unité est remplacée dans sa zone par une autre, à qui sont transférées les responsabilités de mission et de zone ; elle poursuit l’opération en cours.","S’emparer de (to seize) – FR : s’assurer de la possession d’un point ou d’une zone en détruisant, capturant ou chassant l’ennemi qui pourrait l’occuper. OTAN : prendre possession par la force d’une zone ou d’un secteur désigné.","Surveiller (to screen) – FR : observer systématiquement surfaces terrestres, lieux, personnes et objets pour déceler toute activité ennemie en un point, sur une direction ou dans une zone, afin d’alerter et de renseigner. OTAN : observer, identifier et transmettre des informations sur la menace pesant sur la force principale ; on ne se bat que pour assurer sa propre sécurité."]}],
 vig:["Jalonner : sans se laisser identifier ni accrocher.","Recueillir, c’est accueillir une unité qui se replie et la couvrir un certain délai.","Relever n’est pas une mission mais un procédé d’exécution.","Surveiller : on ne se bat que pour sa propre sécurité."],
 quiz:[
 {q:"Quelle mission consiste à renseigner en permanence sur la progression d’un adversaire, sans se laisser identifier ni accrocher ?",o:["Jalonner","Surveiller","Freiner","Éclairer"],a:0,e:"Les éléments mobiles saisissent toute occasion de préciser le renseignement et de causer des pertes."},
 {q:"Quelle mission vise à restreindre l’activité ennemie et à créer un climat d’insécurité ?",o:["Harceler","Fixer","Interdire","Neutraliser"],a:0,e:"Par le feu, des coups de main, des embuscades, des obstacles battus ou non."},
 {q:"Neutraliser, c’est mettre l’adversaire hors d’état d’agir efficacement…",o:["pendant un temps et dans une zone donnés","définitivement","uniquement par des feux indirects","sans délai défini"],a:0,e:"La destruction, elle, est définitive."},
 {q:"Quelle mission consiste à rechercher toutes forces ennemies, caches ou moyens de subsistance dans un secteur ?",o:["Ratisser","Nettoyer","Reconnaître","Boucler"],a:0,e:"Ratisser (to search)."},
 {q:"Recueillir consiste à…",o:["soutenir une unité qui se replie, lui faire franchir son propre dispositif puis la couvrir un certain délai","relever une unité sur position en lui substituant ses propres moyens, puis la remplacer dans sa mission","poursuivre un ennemi en repli, le déborder sur ses flancs puis l’empêcher de se rétablir sur une ligne","rassembler les renseignements recueillis par les unités au contact puis les diffuser à l’échelon supérieur"],a:0,e:"Le recueil n’a pas de symbole."},
 {q:"Relever est…",o:["un procédé d’exécution","une mission offensive","un MAG","une mission de sécurisation"],a:0,e:"Il se fait sur position, par dépassement ou par recueil."},
 {q:"Dans une relève sur position, que reçoit l’unité remplaçante ?",o:["Les responsabilités de mission et de zone","Uniquement la zone","Uniquement le matériel","Rien, elle reste en réserve"],a:0,e:"Elle poursuit l’opération en cours."},
 {q:"S’emparer de, c’est s’assurer de la possession d’un point ou d’une zone…",o:["en détruisant, capturant ou chassant l’ennemi qui pourrait l’occuper","sans opposition, en s’y installant avant l’arrivée de l’ennemi","par la seule observation, en la battant de ses feux sans l’occuper","en le contournant, pour isoler l’ennemi qui pourrait l’occuper"],a:0,e:"Occuper, au contraire, se fait sans opposition."},
 {q:"En surveillance, selon l’OTAN, on se bat…",o:["seulement pour assurer sa propre sécurité","pour détruire l’ennemi","pour tenir le terrain","jamais, même en légitime défense"],a:0,e:"On observe, identifie et transmet les informations sur la menace."},
 {q:"Quelle mission de GTIA peut se faire sur un point, une zone, un itinéraire, un axe ou une direction, en engageant éventuellement le combat ?",o:["Reconnaître","Éclairer","Surveiller","Jalonner"],a:0,e:"Reconnaître : aller chercher le renseignement tactique ou technique."},
 {q:"Selon l’OTAN, infiltrer consiste à se déplacer…",o:["d’un environnement non hostile vers un environnement hostile sans être détecté","d’un environnement hostile vers un environnement non hostile","au contact de l’ennemi en combattant","sur un itinéraire contrôlé"],a:0,e:"L’inverse est l’exfiltration."},
 {q:"Réduire une résistance, c’est notamment…",o:["détruire les reliquats localisés et fixés d’une formation déjà amoindrie","contourner une résistance pour la laisser aux unités qui suivent","freiner une formation intacte pour permettre le recueil des unités amies","obtenir la reddition d’une formation encerclée sans engager le combat"],a:0,e:"Ou mettre hors de combat un élément repéré, identifié et localisé."}]},
{id:"ms_aut",grp:RF_GRP,title:"Autres missions et tâches",qtag:"Missions",
 but:"Connaître les autres missions et tâches tactiques employées dans les ordres, surtout celles issues du vocabulaire OTAN, et éviter les confusions les plus fréquentes.",
 sections:[
 {h:"De Attaque par le feu à Désorganiser",l:["Attaque par le feu (attack by fire) : tâche par laquelle un chef engage l’ennemi par des tirs directs appuyés par des tirs indirects, sans se rapprocher de lui ; on détruit à distance quand l’occupation de l’objectif n’est pas exigée. Elle revient normalement à l’élément d’appui en offensive et à la réserve en contre-attaque en défensive.","Barrer (direction, itinéraire) (to block) : arrêter un ennemi progressant sur une direction ou un itinéraire ; lui interdire l’accès à une zone ou empêcher son avancée sur un axe. OTAN : effet d’obstacle intégrant feux et obstacles pour arrêter un attaquant sur un axe ou l’empêcher de quitter un secteur d’engagement.","Canaliser (to canalize) : restreindre les opérations dans une zone étroite par des obstacles, des feux, la manœuvre ou la mise en place d’unités. OTAN : limiter le mouvement à une direction désignée.","Capturer (to capture, OTAN) : appréhender du personnel, s’emparer de matériels ou d’informations ennemis.","Conserver (to retain) : tenir une position pour s’assurer qu’elle reste libre de toute occupation ou utilisation hostile.","Contenir (to contain, OTAN) : limiter les mouvements d’un individu, d’un groupe ou d’une organisation à un secteur défini, ou le tenir sous contrôle ; s’applique aussi aux maladies et catastrophes naturelles.","Contourner (to bypass) : manœuvrer autour d’un obstacle, d’une position ou d’une force ennemie pour maintenir le rythme ; on rend compte à l’échelon supérieur des obstacles et forces contournés.","Désorganiser (to disrupt) : action ou effet d’obstacle (feux et obstacles intégrés) qui disloque une formation ennemie, freine son allure, lui fait abandonner ses horaires, entraîne l’engagement prématuré de ses forces ou brise son attaque. OTAN : briser la formation, casser le rythme ou interrompre le cadencement."]},
 {h:"De Embuscade à Occuper",l:["Embuscade (ambush) : depuis des positions camouflées, attaque surprise sur un ennemi en mouvement ou temporairement arrêté.","Envelopper (to envelop, OTAN) : contourner ou passer sur les positions défensives principales ennemies pour s’assurer d’objectifs sur ses arrières.","Escorter (to escort) : accompagner et protéger des véhicules sans moyens propres face à la menace, sur un itinéraire prédéfini non sécurisé (procédé d’exécution) ; OTAN : accompagner et protéger un individu, un groupe, une force ou un convoi.","Évacuer (pour le GTIA-S blindé) : mettre à l’abri des personnes par récupération, regroupement et évacuation, lors d’une intervention armée à l’étranger en climat insurrectionnel.","Exfiltrer (to exfiltrate, OTAN) : déplacer sans être repéré ses propres forces, individuellement ou par petits groupes, d’un environnement hostile vers un environnement non hostile.","Extraire (to recover, OTAN) : récupérer, avec ou sans usage de la force, une force amie, des personnes non hostiles ou du matériel d’un emplacement non contrôlé par les forces amies.","Intercepter (to intercept) : détruire ou au minimum neutraliser des éléments adverses infiltrés ou en cours d’infiltration dans une zone.","Isoler (to isolate, OTAN) : couper, physiquement ou psychologiquement, une cible de son soutien, lui interdire la liberté de mouvement et les contacts avec d’autres éléments.","Nettoyer (to clear) : détruire un ennemi résiduel, encerclé ou dépassé. OTAN : supprimer toute résistance dans un secteur, ou forcer une cible à le quitter.","Occuper (to occupy) : se rendre sur un objectif, un point clé, une installation ou une portion de terrain sans opposition et le contrôler."]},
 {h:"De Patrouiller à Tenir",l:["Patrouiller (to patrol, OTAN) : envoyer un détachement recueillir des informations, conduire des activités de combat ou assurer une présence dans une zone.","Poursuivre (to pursue, OTAN) : rattraper ou isoler un élément ennemi qui tente de s’échapper, pour le détruire.","Prendre le contact (to gain contact) : pour les éléments de tête, engager le feu avec l’ennemi ou s’infiltrer dans son dispositif pour renseigner, tenir, voire conquérir les points clés utiles à la suite. Préciser le contact (to identify contact) : déterminer où l’ennemi résiste et les intervalles de son dispositif.","Renseigner : acquérir et transmettre des informations opérationnelles, tactiques ou techniques, sur les forces adverses ou le milieu.","Replier (to retire, OTAN) : déplacer une force qui n’est pas au contact, loin de l’ennemi ou d’une situation hostile.","Se replier (to withdraw) : rompre le contact avec l’ennemi et exécuter un mouvement rétrograde.","Rompre le contact (to disengage) : se dérober au contact de l’ennemi ; se soustraire aux coups d’un élément hostile.","Soutenir (to follow and support) : suivre une force menant une opération offensive et l’assister ; ce n’est pas une réserve, elle est engagée sur des tâches précises. Aussi : en sécurisation ou assistance, fournir des moyens ou services à une autre unité, un organisme ou une population.","Suivre en mesure de relever (to follow and assume) : suivre une force en offensive, prêt à reprendre sa mission si elle est fixée, usée ou incapable de continuer ; ce n’est pas une réserve, elle est engagée sur des tâches précises.","Tenir (to hold) : occuper et défendre un point ou un espace de terrain pour empêcher qu’il soit occupé ou utilisé."]},
 {h:"Paires à ne pas confondre",l:["Détruire (définitif) / neutraliser (temporaire, dans un temps et une zone donnés).","Éclairer (sans combat) / reconnaître (en engageant éventuellement le combat) / surveiller (observer pour alerter, combat pour sa seule sécurité) / jalonner (au contact, sans se laisser accrocher).","Replier (hors contact) / se replier (en rompant le contact).","S’emparer de (contre un ennemi) / occuper (sans opposition) / tenir (occuper et défendre) / conserver (garder libre de toute occupation hostile).","Soutenir (assister la force suivie) / suivre en mesure de relever (reprendre sa mission) : ni l’une ni l’autre n’est une réserve.","Infiltrer (vers l’environnement hostile) / exfiltrer (hors de l’environnement hostile) / extraire (récupérer des amis ou du matériel).","Ratisser (rechercher) / nettoyer (détruire l’ennemi résiduel).","Barrer (arrêter sur une direction) / interdire (empêcher l’accès ou l’usage) / boucler (dispositif continu le long d’une ligne)."]}],
 vig:["Préférer les verbes définis aux formulations libres dans les ordres.","Pour l’attaque par le feu, préciser qu’on n’occupe pas l’objectif.","Contourner impose de rendre compte de ce qui a été contourné."],
 quiz:[
 {q:"Quelle tâche engage l’ennemi par tirs directs appuyés de tirs indirects, sans se rapprocher de lui ?",o:["L’attaque par le feu","L’embuscade","Le harcèlement","Le coup d’arrêt"],a:0,e:"Elle détruit à distance quand l’occupation de l’objectif n’est pas exigée."},
 {q:"En offensive, à quel élément revient normalement l’attaque par le feu ?",o:["L’élément d’appui","L’élément d’assaut","L’échelon de découverte","La réserve"],a:0,e:"En défensive, à la réserve en contre-attaque."},
 {q:"Que doit-on faire des obstacles et forces ennemies contournés ?",o:["En rendre compte à l’échelon supérieur","Les détruire avant de poursuivre","Les ignorer","Les signaler seulement après la mission"],a:0,e:"Contourner sert à maintenir le rythme de la progression."},
 {q:"Quelle différence entre « replier » et « se replier » ?",o:["Replier : force hors contact ; se replier : en rompant le contact","Replier : en rompant le contact ; se replier : force hors contact","Aucune : les deux termes traduisent l’anglais « to withdraw »","Replier : terme OTAN ; se replier : terme propre à la doctrine française"],a:0,e:"To retire / to withdraw."},
 {q:"Une force chargée de « soutenir » ou de « suivre en mesure de relever » est-elle une réserve ?",o:["Non, elle est engagée sur des tâches précises","Oui, toujours, puisqu’elle n’est pas au contact","Oui, si le chef le précise dans l’articulation","Seulement en défensive, en arrière des positions"],a:0,e:"Suivre en mesure de relever : prête à reprendre la mission de la force suivie si celle-ci est fixée, usée ou incapable de continuer."},
 {q:"Occuper se fait…",o:["sans opposition","contre un ennemi installé","par infiltration seulement","sous le feu"],a:0,e:"S’emparer de, au contraire, suppose de détruire, capturer ou chasser l’ennemi."},
 {q:"Quelle mission détruit ou neutralise des éléments adverses infiltrés ou en cours d’infiltration ?",o:["Intercepter","Isoler","Ratisser","Boucler"],a:0,e:"Intercepter (to intercept)."},
 {q:"Selon l’OTAN, envelopper consiste à…",o:["contourner ou passer sur les positions principales ennemies pour s’assurer d’objectifs sur ses arrières","attaquer de front les positions principales ennemies pour les fixer avant de les détruire dans la profondeur","encercler complètement une localité ou une position ennemie pour la couper de tout soutien extérieur","isoler une force ennemie de ses soutiens en coupant ses itinéraires logistiques sans engager ses positions"],a:0,e:"To envelop."},
 {q:"Quelle différence entre ratisser et nettoyer ?",o:["Ratisser : rechercher ; nettoyer : détruire l’ennemi résiduel","Aucune","Nettoyer : rechercher des caches ; ratisser : détruire","Ratisser ne concerne que les matériels"],a:0,e:"Nettoyer : ennemi résiduel, encerclé ou dépassé."},
 {q:"Préciser le contact, c’est…",o:["déterminer où l’ennemi résiste et les intervalles de son dispositif","engager le feu pour la première fois afin de renseigner sur l’ennemi","rompre le contact pour se rétablir sur une position plus en arrière","s’infiltrer dans les arrières ennemis pour y tenir les points clés"],a:0,e:"Prendre le contact, c’est engager le feu ou s’infiltrer pour renseigner et tenir les points clés."},
 {q:"Quelle mission consiste à occuper et défendre un point ou un espace pour empêcher qu’il soit occupé ou utilisé ?",o:["Tenir","Conserver","Occuper","Contrôler"],a:0,e:"Conserver : tenir une position pour qu’elle reste libre de toute occupation ou utilisation hostile."},
 {q:"Quel effet d’obstacle disloque une formation, freine son allure, lui fait abandonner ses horaires ou brise son attaque ?",o:["Désorganiser","Barrer","Canaliser","Contourner"],a:0,e:"Désorganiser (to disrupt)."},
 {q:"Selon l’OTAN, canaliser consiste à…",o:["limiter le mouvement à une direction désignée","arrêter l’ennemi sur un axe","encercler l’ennemi","détruire l’ennemi dans une zone étroite"],a:0,e:"En France : restreindre les opérations dans une zone étroite par obstacles, feux, manœuvre ou mise en place d’unités."},
 {q:"Exfiltrer, c’est se déplacer sans être repéré…",o:["d’un environnement hostile vers un environnement non hostile","d’un environnement non hostile vers un environnement hostile","au contact de l’ennemi, en profitant de l’obscurité et des couverts","sous escorte, d’une zone contrôlée vers une autre zone contrôlée"],a:0,e:"Infiltrer est le mouvement inverse."},
 {q:"Barrer une direction, c’est…",o:["arrêter un ennemi qui progresse sur cette direction","observer un ennemi qui progresse sur cette direction","empêcher l’accès ou l’usage de cette direction","reconnaître la direction avant le passage des gros"],a:0,e:"Interdire : empêcher l’accès ou l’usage ; boucler : dispositif continu le long d’une ligne."}]}
];
