FX_LEX.push(["LD","Line of departure – ligne de débouché"],["LOA","Limit of advance – limite de progression"],["FLOT","Forward line of own troops – ligne avant des forces amies"],["FEBA","Forward edge of the battle area – limite avant de la zone de combat"],["LC","Line of contact – ligne des contacts"],["FCL","Final coordination line – ligne de coordination finale"],["PL","Phase line – ligne de coordination"],["LRCL","Ligne de recueil (handover line)"],["FSCL","Fire support coordination line – ligne de coordination des feux d’appui"],["LIA","Ligne d’identification et d’accueil"],["PIA","Point d’identification et d’accueil"],["ZI / AOI","Zone d’intérêt (area of interest)"],["ZO","Zone d’opérations"],["ZA / AOR","Zone d’action (area of responsibility)"],["ZE","Zone d’engagement"],["ZEO","Zone d’effort sur objectif"],["ZDI","Zone de déploiement initial"],["ZDA","Zone de déploiement et d’attente"],["ZDAE","Zone de déploiement et d’attente extension"],["FFA","Free fire area – zone de tirs libres"],["DZ","Drop zone – zone de saut"],["EZ","Extraction zone – zone de largage à faible hauteur"],["LZ","Landing zone – zone d’atterrissage"],["PZ","Pickup zone – zone d’enlèvement par hélicoptère"],["FPF","Final protective fire – tir d’arrêt"],["ENY","Enemy – ennemi (mention portée sur un calque)"],["OHT","Opération d’hélitransport"],["APP-6","Symbologie militaire interarmées OTAN"]);

/* ---------- 7c : commandement et géométrie ---------- */
const CD_MODS=[
{id:"cd_c2",grp:RF_GRP,title:"Relations de commandement et articulation",qtag:"Commandement",
 but:"Maîtriser les relations de commandement (OPCOM, OPCON, TACOM, TACON) et les positions des unités (détachement, renforcement, adaptation), pour rédiger l’articulation et savoir ce que l’on peut faire ou non d’une unité reçue ou placée.",
 sections:[
 {h:"Commandement et contrôle",l:["Le commandement est une responsabilité confiée à un militaire, avec l’autorité pour analyser et apprécier une situation, concevoir, organiser, planifier et décider, donner des ordres et des directives, diriger leur exécution (ou la déléguer, la transférer, puis la vérifier) et en évaluer les résultats. Il inclut le contrôle de moyens qui ne sont pas sous son commandement.","Le contrôle fait partie du commandement : s’assurer du respect des directives et ordres, diriger l’exécution des actions qui en découlent et en évaluer les résultats, sur une partie des activités d’organismes subordonnés ou non. Il peut être délégué ou transféré, en tout ou partie.","Niveau stratégique : fixe les objectifs de sécurité, alloue les ressources et déploie les forces sur un théâtre. Niveau opératif : plus haut niveau interarmées sur le théâtre, où les opérations sont planifiées, conduites et soutenues. Niveau tactique : subordonné, où opérations et actions sont planifiées, préparées et exécutées dans un milieu ou un domaine.","Conduite d’une manœuvre : suite de décisions du chef pour adapter aux circonstances prévues ou imprévues l’exécution de chaque phase. Ordre : expression de la décision du chef, verbale ou écrite, donnant des prescriptions précises exécutables généralement à courte échéance."]},
 {h:"Délégation et transfert d’autorité",l:["Délégation : vers un commandant subordonné, éventuellement assortie de conditions.","Transfert : vers un commandant non subordonné. Il précise au minimum qui exercera l’autorité, les limites exactes du transfert (OPCON, TACOM, fonction tactique, TACON…) avec les éventuelles restrictions nationales (caveats), et le cadre espace-temps (zone, date et heure)."]},
 {h:"Les niveaux d’autorité",l:["FULLCOM (commandement intégral) : pouvoir militaire de plus haut niveau d’un État, strictement national, couvrant opérations et administration ; en France, il est exercé par le CEMA. Il comprend le contrôle administratif (ADCON) et le commandement opérationnel (OPCOM), lequel se décline en OPCON, TACOM, fonctions tactiques et TACON.","OPCOM (commandement opérationnel) : autorité d’un commandant de niveau stratégique pour définir le cadre d’engagement, affecter ou réaffecter des forces, déployer des unités et assigner des missions. Hors du territoire national, le CEMA conserve toujours l’OPCOM des moyens français engagés, en opération nationale comme multinationale.","OPCON (contrôle opérationnel) : autorité pour déployer en intra-théâtre et employer des forces dans un cadre espace-temps et selon les directives du commandant opérationnel ; il peut être délégué ou transféré, en tout ou partie.","TACOM (commandement tactique) : autorité déléguée, ou transférée par un contrôleur opérationnel, pour définir et attribuer des missions ou des tâches aux forces placées sous ce commandement ou mises à disposition. Le TACOM n’existe pas en doctrine américaine.","TACON (contrôle tactique) : direction détaillée, normalement locale, des mouvements ou manœuvres nécessaires pour exécuter les missions ou tâches assignées."]},
 {h:"Ce que permet chaque autorité",tb:{cols:["Prérogative","FULLCOM","OPCOM","OPCON","TACOM","TACON"],rows:[["Exercée au niveau tactique","–","–","✓ (au niveau commandant de composante)","✓","✓"],["Exercée à un niveau sub-tactique","–","–","–","✓","✓"],["Affecter des moyens à une opération","✓","✓","–","–","–"],["Déployer des moyens vers le théâtre","–","✓","–","–","–"],["Déployer des moyens en intra-théâtre","–","✓","✓","–","–"],["Modifier l’affectation au sein d’une même opération","–","–","✓ (par transfert d’OPCON)","✓ (par transfert de TACOM)","–"],["Fixer des missions à des moyens","–","sous conditions","✓ (si retenu à ce niveau)","✓","–"],["Fixer des tâches à des moyens","–","sous conditions","✓ (si retenu à ce niveau)","✓","–"],["Diriger les mouvements et manœuvres","–","sous conditions","✓ (si retenu à ce niveau)","✓ (si retenu à ce niveau)","✓"],["Responsabilité administrative (ADCON)","✓","–","–","–","–"]]},
  l:["Délégation à un subordonné : l’OPCON peut déléguer OPCON (seulement pour un commandant de niveau stratégique ou opératif), TACOM et TACON ; le TACOM peut déléguer TACOM et TACON ; le TACON, le TACON. Transfert à un non-subordonné : l’OPCON peut transférer OPCON, TACOM et TACON ; le TACOM et le TACON, seulement le TACON."]},
 {h:"Pour retenir l’essentiel",tb:{cols:["Situation","Je peux","Je dois","Je ne peux pas","Exemple"],rows:[
  ["Je reçois une unité sous OPCON","Lui donner des missions ; lui donner en renforcement, la détacher ou l’adapter","Lui définir ses rôles et missions dans un PS ou un OPORD, comme toute unité de ma BIA","Lui prélever des unités","1 GTIA d’éléments organiques divisionnaires en renforcement de la BIA"],
  ["Je place une unité sous OPCON","La renforcer, la détacher ou l’adapter ; lui prélever des unités (une partie conservée aux ordres)","Remplir le paragraphe articulation (l’OPCON est le commandement « par défaut »)","Lui définir ses rôles et tâches : c’est à son contrôleur opérationnel de le faire","Un bataillon d’infanterie renforcé d’une compagnie de combat du génie, d’une section MISTRAL et d’un EOC"],
  ["Je reçois une unité sous TACOM","Lui donner des tâches dans le cadre de la mission que lui a donnée son contrôleur opérationnel ; la renforcer si c’est compatible avec sa mission","Lui définir ses tâches dans le PS ou l’OPORD ; définir les mesures de coordination, y compris son retour aux ordres à l’issue","Lui donner des tâches incompatibles avec sa mission ; lui prélever des unités","Un SGAM d’attaque en soutien de la BIA entre deux GDH : la division donne la mission générale, la BIA les tâches qui en découlent"],
  ["Je place une unité sous TACOM","La renforcer, la détacher ou l’adapter ; lui prélever des unités (une partie conservée aux ordres)","Lui donner sa mission avec un GDH ; préciser « sous TACOM » dans l’articulation","Changer sa mission sans préavis alors qu’elle est encore sous TACOM","Une section sol-air sous TACOM d’un GTIA en défensive jusqu’à un GDH"],
  ["Je reçois une unité sous TACON","Lui fixer les mesures de coordination (mouvements, manœuvres) nécessaires à sa mission","Définir les mesures de coordination","Lui donner des missions ou des tâches : elle arrive avec sa mission, ses tâches et ses moyens fixés par son contrôleur opérationnel","Le SGAM chargé de l’opération héliportée de la BIA, à l’exclusion de toute autre tâche"],
  ["Je place une unité sous TACON","Fixer jusqu’aux mesures de coordination, même s’il est préférable de les laisser établir par l’unité qui a le TACON","Préciser « sous TACON » dans l’articulation ; donner la mission et définir les tâches de l’unité","(À éviter) changer sa mission sans préavis alors qu’elle est encore sous TACON","Le DLRG sous TACON de l’EEI (il a sa mission propre mais manœuvre dans le sillage de l’EEI) ; un GTIA qui traverse la zone d’un autre pour se mettre en place"]]},
  l:["Il est toutefois possible de prélever des unités à une unité reçue sous OPCON si l’opération est strictement nationale, ou si l’autorité qui détient l’OPCOM sur cette unité donne son accord explicite."]},
 {h:"Détachement, renforcement, adaptation et articulation",l:["Détachement : partie d’une unité détachée de la formation principale pour une mission en d’autres lieux. Une unité détachée est donnée en renforcement ou adaptée.","Renforcement : unité mise pour emploi à la disposition d’un échelon déjà pourvu de formations de ce type, pour en augmenter les capacités.","Adaptation : unité mise pour emploi à la disposition d’un échelon qui en est organiquement dépourvu.","Une unité en renforcement ou en prélèvement s’accompagne d’un chef et de moyens de commandement et de liaison.","Le paragraphe articulation est le dernier de l’idée de manœuvre d’un PS et le paragraphe 0 d’un OPO ; il est parfois reporté en annexe. Les unités reçues sous OPCON doivent y figurer, ainsi que celles reçues sous TACON ou TACOM qui participent à la mission de la grande unité.","L’articulation est arrêtée à l’issue de la réunion de décision : elle fait partie intégrante du mode d’action."],go:["or_opo"]}],
 vig:["OPCON : je donne des missions, je ne prélève pas (sauf opération nationale ou accord de l’OPCOM).","TACOM : je donne des tâches dans le cadre de sa mission, avec un GDH de fin.","TACON : seulement des mesures de coordination.","Renforcement : l’échelon a déjà ce type d’unité ; adaptation : il en est dépourvu."],
 apply:[{t:"note",x:"Rédige l’articulation de ta brigade : pour chaque unité reçue ou placée, la relation de commandement, sa position, la période et ce que tu peux ou non lui ordonner."},
  {t:"table",id:"cdart",l:"Articulation et relations de commandement",cols:[{k:"u",l:"Unité"},{k:"r",l:"Relation",o:["Organique","OPCON","TACOM","TACON"]},{k:"p",l:"Position",o:["Renforcement","Adaptation","Détachement","Prélèvement"]},{k:"a",l:"Au profit de"},{k:"h",l:"Du (GDH) au (GDH)"},{k:"c",l:"Conditions ou restrictions",s:1}]},
  {t:"doc",l:"Articulation et relations de commandement"}],
 quiz:[
 {q:"Vers qui s’effectue une délégation d’autorité ?",o:["Vers un commandant subordonné","Vers un commandant non subordonné","Vers l’échelon supérieur","Vers une nation alliée"],a:0,e:"Vers un commandant non subordonné, c’est un transfert."},
 {q:"Que doit préciser au minimum un transfert d’autorité ?",o:["Le bénéficiaire, les limites du transfert avec les caveats, et le cadre espace-temps","La date et l’heure du transfert, les effectifs concernés et leur dotation logistique","Les effectifs, la logistique associée et le niveau d’entraînement de l’unité transférée","La seule zone d’emploi, l’échelon de rattachement logistique et le plan de transmissions"],a:0,e:"Identité, limites (OPCON, TACOM, TACON…), zone, date et heure."},
 {q:"Qui exerce le FULLCOM en France ?",o:["Le CEMA","Le CEMAT","Le commandant de la force","Le COMDIV"],a:0,e:"Hors du territoire national, il conserve toujours l’OPCOM des moyens français."},
 {q:"Quelle autorité permet de déployer des forces en intra-théâtre et de les employer dans un cadre espace-temps ?",o:["L’OPCON","Le TACON","Le TACOM","L’ADCON"],a:0,e:"L’OPCON peut être délégué ou transféré, en tout ou partie."},
 {q:"Quelle autorité se limite à la direction détaillée, normalement locale, des mouvements et manœuvres ?",o:["Le TACON","Le TACOM","L’OPCON","L’OPCOM"],a:0,e:"Le TACON ne permet pas de donner missions ou tâches."},
 {q:"Dans quelle doctrine le TACOM n’existe-t-il pas ?",o:["La doctrine américaine","La doctrine française","La doctrine OTAN","La doctrine britannique"],a:0,e:"L’outil emploie les termes dans leur acception OTAN."},
 {q:"J’ai reçu une unité sous OPCON : que ne puis-je pas faire, en règle générale ?",o:["Lui prélever des unités","Lui donner des missions","La donner en renforcement","Lui définir ses rôles dans l’OPORD"],a:0,e:"Sauf opération strictement nationale ou accord explicite de l’autorité qui détient l’OPCOM."},
 {q:"J’ai reçu une unité sous TACOM : que puis-je lui donner ?",o:["Des tâches dans le cadre de la mission fixée par son contrôleur opérationnel","Une nouvelle mission de mon choix, avec préavis à son contrôleur opérationnel","Des tâches de mon choix, y compris en prélevant des unités sur sa structure","Uniquement des mesures de coordination, sa mission et ses tâches étant fixées"],a:0,e:"Je ne peux lui donner de tâches incompatibles avec sa mission ni lui prélever des unités."},
 {q:"J’ai reçu une unité sous TACON : que puis-je lui fixer ?",o:["Les mesures de coordination nécessaires à sa mission","Sa mission, dans le cadre de celle de ma propre unité","Ses tâches, dans le cadre de la mission déjà reçue","Ses moyens, en lui adjoignant ou prélevant des unités"],a:0,e:"Elle arrive avec sa mission, ses tâches et ses moyens fixés par son contrôleur opérationnel."},
 {q:"Je place une unité sous TACOM : que dois-je faire ?",o:["Lui donner sa mission avec un GDH et préciser « sous TACOM » dans l’articulation","Lui définir toutes ses tâches de détail et préciser « sous TACON » dans l’articulation","Rien de plus : la mention « sous TACOM » dans l’articulation suffit à l’engager","La retirer de l’articulation et lui adresser sa mission par un ordre particulier"],a:0,e:"Je ne peux pas changer sa mission sans préavis pendant le TACOM."},
 {q:"Comment appelle-t-on la mise à disposition d’une unité au profit d’un échelon qui en est organiquement dépourvu ?",o:["L’adaptation","Le renforcement","Le détachement","Le prélèvement"],a:0,e:"Le renforcement augmente les capacités d’un échelon déjà pourvu de ce type d’unité."},
 {q:"Où figure le paragraphe articulation dans un OPO ?",o:["Paragraphe 0","Paragraphe 3","En annexe obligatoirement","Il n’y figure pas"],a:0,e:"Dans un PS, c’est le dernier paragraphe de l’idée de manœuvre."},
 {q:"Quand l’articulation est-elle arrêtée ?",o:["À l’issue de la réunion de décision","Dès l’analyse de la mission","Au mission brief","Au back brief"],a:0,e:"Elle fait partie intégrante du mode d’action."},
 {q:"Qu’accompagne obligatoirement une unité donnée en renforcement ou prélevée ?",o:["Un chef et des moyens de commandement et de liaison","Un officier de renseignement et un poste radio","Une section logistique et ses lots de ravitaillement","Un détachement NRBC et des moyens de décontamination"],a:0,e:"C’est une condition de l’articulation."}]},
{id:"cd_geo",grp:RF_GRP,title:"Géométrie de l’espace de bataille et gestion de l’espace",qtag:"Commandement",
 but:"Connaître le découpage de l’espace de bataille (ZOP, ZOR, ZOAR, zone arrière) et les principes de la gestion de l’espace terrestre, pour définir et coordonner les zones de la brigade et de ses GTIA.",
 sections:[
 {h:"Les zones de l’espace de bataille",l:["Zone des opérations dans la profondeur (ZOP, deep area) : l’échelon considéré (corps d’armée, division ou brigade) y modèle l’ennemi avant qu’il n’arrive au contact de ses subordonnés ; il y renseigne, combat, désorganise et met l’ennemi à temps et à portée de ses unités.","Zone des opérations rapprochées (ZOR, close area) : l’échelon y déploie le gros de ses unités de manœuvre et y mène les principaux combats de contact. Elle s’étend de la limite avant de la ZOAR à la limite arrière de la ZOP ; c’est sa zone d’engagement.","Zone des opérations arrière (ZOAR, support area) : positionnement et emploi des unités, surtout de soutien, nécessaires aux opérations dans la ZOR. Elle n’existe qu’aux niveaux corps d’armée et division.","Zone arrière (ZAR, rear area) : l’unité y crée les conditions de la victoire, surtout par le soutien, la protection, l’agencement de l’espace terrestre, la consolidation des acquis et la maîtrise des flux.","Pour les feux, au niveau 3 : la ZOR s’étend de la zone d’implantation des GTIA de 1er échelon jusqu’à la portée maximale des armes à tir tendu (4 km), où se font les tirs d’appui direct ; la ZOP va au-delà jusqu’à la limite de la zone de responsabilité de la brigade, où se font généralement les tirs d’action d’ensemble."],go:["f3_art"]},
 {h:"Zones de la division et de la brigade",l:["La zone d’opération d’une division peut aller de 60 à 120 km de front sur 450 km de profondeur, selon sa composition, sa mission et le terrain ; elle agit dans toute cette zone.","En déploiement préliminaire, la division peut attribuer à ses unités une zone de déploiement et d’attente (ZDA) près de leur zone d’action future.","Dispositif continu : les zones d’opérations des brigades sont généralement contiguës. Dispositif lacunaire : elles sont séparées par des zones lacunaires (ZL), sous la surveillance et la responsabilité de la division. Le découpage évolue en permanence en conduite.","La division fixe la zone d’opération de la brigade dans sa ZOR, selon le terrain, la menace, le MAG confié et les capacités d’appui-feu ; la brigade détermine de même les zones d’action de ses GTIA.","La brigade est responsable de la coordination, du stationnement et du contrôle des mouvements de toutes les unités présentes dans sa zone, y compris des unités de la division qui y évoluent."]},
 {h:"La gestion de l’espace terrestre (LSM)",l:["Déclinaison terrestre du battle space management (BSM), le land space management (LSM), anciennement GESTER, regroupe les moyens et mesures qui coordonnent, synchronisent et priorisent, de façon planifiée ou dynamique, les activités sur l’espace terrestre et souterrain.","Il s’appuie sur les gabarits d’engagement et d’empreinte au sol des unités (y compris PC et relais), le réseau de manœuvre et logistique et ses élongations, la sûreté et la défense sol-air, la menace ennemie et ses portées, l’historique des munitions explosives et zones polluées, les risques naturels et industriels, la portée des communications, la population et les besoins des unités (infrastructures, points hauts, lisières, couverts…).","L’empreinte au sol inclut la traînée de l’unité : ses flux montants et descendants, lourds de conséquences pour le mouvement, le stationnement et la protection.","Principe : attribuer à chaque chef tactique une zone d’opération délimitée où il a autorité pour planifier et conduire, et définir les modalités d’interaction de plusieurs unités dans une même zone. Le LSM relève des bureaux génie des niveaux 2 et 3 ; il est suivi par la cellule S3/2D des PC de GTIA.","Mesures géographiques, souvent assorties de délais : zones (objectifs, rassemblement, attente, engagement, zones réglementées, zones d’effort des feux, d’engagement ALAT…), points (jonction, franchissement, dislocation…), lignes de contrôle et de coordination (LD, ligne de recueil, FLOT, LOA…) et limites entre unités."],go:["sy_mcc"]},
 {h:"Le battle space management (BSM)",l:["Le BSM ne coordonne pas les effets : il répartit les moyens dans l’espace terrestre (2D : stationnement, circulation, flux), l’espace aérien (3D : acteurs de la 3e dimension) et le spectre cyber et électromagnétique (4D : moyens et réseaux).","Il se pense dès la conception des ordres puis se gère en conduite."],go:["f3_ci3d","ap_ac4d"]},
 {h:"La brigade de zone arrière (BZA)",l:["Une brigade peut recevoir la responsabilité de la zone arrière de la division : elle appuie et soutient l’action des unités au contact et dans la profondeur, garantit l’accès aux ressources et contribue à la protection de la force et au contrôle de la zone arrière.","Elle est « battle space owner » de la zone arrière : les unités qui y stationnent relèvent de son autorité pour le déploiement et les mouvements.","Tâches : contrôle de la zone arrière (area security), contrôle du stationnement et des mouvements, traficabilité des axes logistiques, protection des sites statiques (PC, éléments logistiques…) dans la ZOAR et la ZOR, protection des convois, prise en compte des prisonniers de guerre, suivi des personnes déplacées, relations avec les autorités et forces de sécurité de la nation hôte."]}],
 vig:["ZOP : modeler ; ZOR : combattre au contact ; ZOAR : soutenir (corps d’armée et division seulement).","La brigade coordonne tout ce qui stationne ou circule dans sa zone.","Penser l’empreinte au sol avec sa traînée logistique.","BSM : 2D, 3D, 4D dès la conception."],
 quiz:[
 {q:"Dans quelle zone l’échelon considéré modèle-t-il l’ennemi avant qu’il n’arrive au contact de ses subordonnés ?",o:["La ZOP","La ZOR","La ZOAR","La zone arrière"],a:0,e:"Il y renseigne, combat, désorganise et met l’ennemi à temps et à portée."},
 {q:"Quelle zone correspond à la zone d’engagement de l’échelon considéré ?",o:["La ZOR","La ZOP","La ZOAR","La ZL"],a:0,e:"Il y déploie le gros de ses unités de manœuvre."},
 {q:"À quels niveaux la ZOAR existe-t-elle ?",o:["Corps d’armée et division","Brigade et GTIA","Tous les niveaux","Division seulement"],a:0,e:"Elle accueille surtout les unités de soutien nécessaires à la ZOR."},
 {q:"Pour les feux au niveau 3, jusqu’où s’étend la ZOR ?",o:["Jusqu’à la portée maximale des armes à tir tendu, 4 km","Jusqu’à 15 km","Jusqu’à la limite de la zone de responsabilité de la brigade","Jusqu’à la FSCL"],a:0,e:"On y réalise les tirs d’appui direct ; au-delà, la ZOP, siège des tirs d’action d’ensemble."},
 {q:"Quelle profondeur peut atteindre la zone d’opération d’une division ?",o:["450 km","120 km","60 km","1 000 km"],a:0,e:"Pour 60 à 120 km de front."},
 {q:"Qu’est-ce qui sépare les zones d’opérations des brigades dans un dispositif lacunaire ?",o:["Des zones lacunaires (ZL)","Des ZOAR","Des zones de déploiement et d’attente","Rien"],a:0,e:"Elles restent sous la surveillance et la responsabilité de la division."},
 {q:"Qui est responsable de la coordination, du stationnement et du contrôle des mouvements dans la zone de la brigade ?",o:["La brigade","La division","Chaque unité pour elle-même","Le régiment du génie"],a:0,e:"Y compris pour les unités de la division qui y évoluent."},
 {q:"Comment s’appelait autrefois le LSM ?",o:["GESTER","BSM","CI3D","GTRS"],a:0,e:"Gestion de l’espace terrestre."},
 {q:"Quels bureaux sont chargés du LSM aux niveaux 2 et 3 ?",o:["Les bureaux génie","Les bureaux renseignement","Les bureaux logistiques","Les bureaux SIC"],a:0,e:"Il est suivi par la cellule S3/2D des PC de GTIA."},
 {q:"Que désigne la traînée d’une unité ?",o:["Ses flux montants et descendants","Son échelon de découverte","Sa réserve","Sa zone de recueil"],a:0,e:"Elle pèse sur le mouvement, le stationnement et la protection."},
 {q:"Que répartit le BSM ?",o:["Les moyens dans les espaces 2D, 3D et 4D","Les effets dans les champs immatériels","Les missions des GTIA","Les crédits de munitions"],a:0,e:"Il ne vise pas la coordination des effets."},
 {q:"Que signifie qu’une brigade de zone arrière est « battle space owner » ?",o:["Les unités qui y stationnent relèvent de son autorité pour le déploiement et les mouvements","Elle commande toutes les unités de la division qui traversent la zone, y compris pour leur mission","Elle seule peut y délivrer des feux, les autres unités devant lui demander leur autorisation","Elle n’a pas de zone propre et partage la zone arrière avec la brigade de soutien divisionnaire"],a:0,e:"Elle contrôle la zone arrière de la division."}]},
{id:"cd_pc",grp:RF_GRP,title:"Le PC de la brigade et ses bascules",qtag:"Commandement",
 but:"Connaître les organisations possibles du PC de brigade, les règles de sa manœuvre et de ses bascules, et le rôle de ses principales fonctions, pour situer le travail de l’état-major pendant la MEDOT et la conduite.",
 sections:[
 {h:"Les quatre espaces du CO",l:["Aux ordres du chef CO et sous la responsabilité du CEM, le CO s’organise en quatre espaces : le groupe de commandement (orientations, directives, décisions) ; la cellule MANFUT (manœuvre future) ; les cellules du CO chargées de l’exécution ; la cellule de management de l’information (CMI), d’accès facile pour toutes les cellules."]},
 {h:"Les organisations possibles du PC",l:["PC unique : une seule installation remplit toutes les fonctions pour toute la zone ; principe d’un PC de combat (PCC) léger et mobile à l’avant de la zone, relativement protégé de l’artillerie adverse.","Deux PC miroirs : deux PC identiques (PC1 et PC2) qui commandent à tour de rôle, pour des bascules fluides et rapides.","Système « 2 + 1 » : deux PC avant mobiles et légers capables de conduire la manœuvre, et un PC arrière plus stable regroupant le soutien et la MANFUT.","PC tactique (PC TAC) : installation mobile, toujours armable, d’où un chef commande au plus près pour une action particulière ou secondaire.","PC Harpon : embryon de PC déployé en précurseur sur la position future du PC, avec des moyens prélevés sur celui-ci."]},
 {h:"La manœuvre des PC et les bascules",l:["On déplace les PC en mode passif puis on les active le temps du stationnement ; le commandement en mouvement reste l’apanage des petits échelons ou du PC TAC.","Bascule : transfert immédiat de responsabilité exécuté à un horaire précis, après un préavis, pour maintenir la continuité des liaisons et la permanence du commandement malgré le mouvement d’un PC. Elle fait en général l’objet d’un FRAGO.","Bascule programmée : ordonnée et préparée, pour déplacer le PC principal. Bascule inopinée : reprise « à la volée » par le PC moyens réservés (PCMR) en cas de dysfonctionnement, de destruction ou d’échec d’une bascule programmée ; elle suppose un PCMR opérationnel.","Stabilité minimale d’un PC de brigade : 8 à 12 h, sous peine d’user le personnel et d’interrompre la rédaction des ordres. Au combat, au plus deux déplacements par 24 h.","Le PC actif se place entre 10 et 25 km de la FLOT ; si le chef doit être plus près, il utilise son PC TAC. Ne jamais basculer à un moment critique (changement de phase, effet majeur…).","Le CEM organise la bascule en trois temps : conception, décision, conduite. Le PC principal n’est désactivé que sur ordre, pour garder la réversibilité.","Pour durer, on travaille par bordées (deux peuvent suffire) ; la relève se fait autant que possible par contact physique, chacun prenant ses consignes auprès de son homologue autour du point de situation de bascule."],go:["normes"]},
 {h:"Le groupe de commandement",l:["Général commandant la brigade (COMBRIG) : commande les chefs de corps des groupements, donne ses directives au CEM, oriente et approuve les travaux et les ordres, décide, suit l’action et rend compte au commandant de division en proposant l’emploi futur de la brigade.","Colonel adjoint (COLADJ) : remplace le général ; peut assurer la permanence du commandement, contrôler l’exécution des phases décisives, commander une opération particulière depuis le PC TAC, diriger ponctuellement la MANFUT ou commander un GTIA.","Chef d’état-major (CEM) : chef et animateur du système des PC, garant de l’esprit des ordres du général ; il oriente et vérifie la MANFUT, conduit les mesures d’urgence, organise la permanence du commandement et prépare les bascules. Il est suppléé par le chef MANFUT ou le chef CO.","Conseillers artillerie et génie (chefs de corps), chef de site (protection et soutien du site de PC), cellule communication en opérations (COMOPS)."]},
 {h:"Les cellules du pôle opérations",l:["MANFUT : commandée par le chef B3 et renforcée en planification par les chefs des cellules spécialisées ; anticipe les phases ultérieures, pilote le processus décisionnel, rédige FRAGO et WINGO, transmet le plan de manœuvre au CO, élabore le compendium et initie la synchromatrice.","Chef CO : rythme le travail du CO (messagerie, points de situation, bascules) selon le compendium et le rythme de bataille ; coordonne les cellules, conduit l’action des GTIA au contact, maîtrise la circulation de l’information.","B2 / RENS : appuie les opérations par le renseignement. B3 / MANEC (manœuvre en cours), cœur du CO : une cellule synthèse (main courante validée toutes les heures par le chef CO, carte de situation, ordres de circonstance, suivi de la synchromatrice) et une cellule conduite (suivi tactique, coordination par ordres simples, alerte sur les mesures urgentes : tirs, NRBC, EVASAN).","OPS/2D (génie, NRBC, contre-minage), OPS/3D (FSCC, avec les DL ALAT), ECIM/5D (effets dans les champs immatériels), pôle logistique, B6/4D (SIC) et CMI (traitement, transfert de l’information, fonctions techniques)."],go:["ac_co","rn_b2","f3_fscc","fx_ecim","ap_ac4d"]}],
 vig:["Stabilité d’un PC de brigade : 8 à 12 h ; au plus deux déplacements par 24 h.","PC actif entre 10 et 25 km de la FLOT ; le PC TAC pour aller plus près.","Jamais de bascule à un moment critique ; le PC principal ne se désactive que sur ordre.","MANFUT : manœuvre future et ordres à venir ; MANEC : action en cours."],
 quiz:[
 {q:"Comment définit-on une bascule de PC ?",o:["Un transfert immédiat de responsabilité à un horaire précis, après un préavis","Un déplacement du PC vers une nouvelle position sans transfert de responsabilité","Un transfert progressif de responsabilité sur plusieurs heures, sans préavis","Une relève de bordée au sein du CO, à heure fixe et selon un tableau de service"],a:0,e:"Elle fait en général l’objet d’un FRAGO."},
 {q:"Quel PC reprend le commandement lors d’une bascule inopinée ?",o:["Le PC moyens réservés (PCMR)","Le PC TAC","Le PC Harpon","Le PC de la division"],a:0,e:"Une bascule inopinée suppose un PCMR opérationnel."},
 {q:"Quelle stabilité minimale doit conserver un PC de brigade en phase d’intervention ?",o:["8 à 12 h","2 à 4 h","24 h","48 h"],a:0,e:"Sous peine d’user le personnel et d’interrompre la rédaction des ordres."},
 {q:"À quelle distance de la FLOT se place le PC actif ?",o:["Entre 10 et 25 km","Entre 2 et 5 km","Entre 30 et 50 km","Au contact"],a:0,e:"Plus près, le chef utilise son PC TAC."},
 {q:"Combien de fois au plus le PC de brigade se déplace-t-il par 24 h au combat ?",o:["Deux","Une","Quatre","Six"],a:0,e:"Selon le rythme de la manœuvre."},
 {q:"Qu’est-ce qu’un PC Harpon ?",o:["L’embryon d’un PC déployé en précurseur sur sa position future","Un PC de combat déployé à l’avant au plus près des unités engagées","Le PC de la réserve, maintenu en arrière jusqu’à son engagement","Un PC miroir qui duplique le PC principal en cas de destruction"],a:0,e:"Ses moyens sont prélevés sur le PC."},
 {q:"Quel système de PC comprend deux PC avant légers et un PC arrière plus stable ?",o:["Le système « 2 + 1 »","Les PC miroirs","Le PC unique","Le PC TAC"],a:0,e:"Le PC arrière regroupe le soutien et la MANFUT."},
 {q:"Qui organise la bascule du PC actif vers le PC réservé ?",o:["Le chef d’état-major","Le général","Le chef B6","Le chef de site"],a:0,e:"En trois temps : conception, décision, conduite."},
 {q:"Qui commande la cellule MANFUT ?",o:["Le chef B3","Le chef CO","Le CEM","Le chef B2"],a:0,e:"Elle est renforcée en planification par les chefs des cellules spécialisées."},
 {q:"Quelle cellule est le cœur du CO et contrôle l’action en cours ?",o:["B3 / MANEC","MANFUT","CMI","ECIM/5D"],a:0,e:"Elle peut se scinder en cellule synthèse et cellule conduite."},
 {q:"Quand peut-on faire basculer le PC ?",o:["Jamais à un moment critique comme un changement de phase ou l’effet majeur","De préférence au moment de l’effet majeur, pour bénéficier de la surprise","À heure fixe, toutes les 6 h, pour garantir la permanence du commandement","Uniquement de nuit, pour limiter la signature électromagnétique du PC"],a:0,e:"Le PC principal n’est désactivé que sur ordre."},
 {q:"Quelles sont les quatre espaces du CO ?",o:["Groupe de commandement, MANFUT, cellules d’exécution, CMI","Synthèse, conduite, cellule 2D et cellule 3D","PC principal, PC tactique, PC arrière, PC Harpon","Groupe de commandement, B2, B3, centre de transmissions"],a:0,e:"Aux ordres du chef CO, sous la responsabilité du CEM."}]}
];
FX_MODS.push(...CD_MODS);
FX_ENC.push(
 ["p1e4",{h:"Référentiel : relations de commandement",l:["Pour chaque unité reçue, noter la relation (OPCON, TACOM, TACON) et la période : elle dit ce que l’on peut lui ordonner."],go:["cd_c2"]}],
 ["p2e6",{h:"Référentiel : articulation",l:["L’articulation est arrêtée à l’issue de la réunion de décision : vérifier relations de commandement, renforcements, adaptations et prélèvements, chacun avec un chef et des moyens de liaison."],go:["cd_c2"]}],
 ["p1e2",{h:"Référentiel : géométrie de l’espace",l:["Situer la zone de la brigade dans la ZOR de la division, ses limites, les zones lacunaires et les unités de la division qui y évoluent."],go:["cd_geo"]}]
);
FX_LEX.push(["FULLCOM","Full command – commandement intégral"],["OPCOM","Operational command – commandement opérationnel"],["TACON","Tactical control – contrôle tactique"],["ADCON","Administrative control – contrôle administratif"],["ZAR","Zone arrière (rear area)"],["ZL","Zone lacunaire"],["LSM","Land space management – gestion de l’espace terrestre (anciennement GESTER)"],["BZA","Brigade de zone arrière"],["PCMR","PC moyens réservés"],["PCC","PC de combat"],["PC TAC","PC tactique"],["MANFUT","Manœuvre future (cellule)"],["MANEC","Manœuvre en cours (cellule)"],["CCO","Chef du centre opérationnel"],["COMBRIG","Général commandant la brigade"],["COLADJ","Colonel adjoint"],["CEM","Chef d’état-major"],["COMOPS","Communication en opérations"]);
if(typeof LEX!=="undefined"){const z=LEX.find(x=>x[0]==="ZOP / ZOR / ZOAR");if(z)z[1]="Zone des opérations dans la profondeur / des opérations rapprochées / des opérations arrière";}

