FX_LEX.push(["NRBC","Nucléaire, radiologique, biologique et chimique"],["ENI / AMI","Ennemi / ami (abréviations des ordres et des calques)"],["RAPFOR","Rapport de forces"],["RENS","Renseignement"],["LOG","Logistique"],["OPS","Opérations"],["ROE","Rules of engagement – règles d’engagement"],["VAB","Véhicule de l’avant blindé"],["PFM","Pont flottant motorisé"],["OI / OG / ONG","Organisation internationale / gouvernementale / non gouvernementale"],["EVASAN","Évacuation sanitaire"],["EM","État-major"],["QG","Quartier général"],["CA","Corps d’armée"],["DIV","Division"],["HF / VHF","Haute fréquence / très haute fréquence (bandes radio)"],["LRU","Lance-roquettes unitaire"],["ACA","Airspace coordination area – zone de coordination de l’espace aérien"],["MEPAC","Mortier embarqué pour l’appui au contact"],["SSI","Sécurité des systèmes d’information"],["LCC","Land component command – commandement de la composante terrestre"],["BOI","Bureau opérations instruction (régiment)"],["COMANFOR","Commandant de la force"],["COMDIV","Commandant de la division"],["COMGTIA","Commandant du GTIA"],["ASA","Artillerie sol-air"],["ROIM","Renseignement d’origine image"],["MGRS","Military grid reference system – système de quadrillage militaire"],["ONU","Organisation des Nations unies"],["CR","Compte rendu"],["RECO","Reconnaissance"],["CEMA","Chef d’état-major des armées"],["CEMAT","Chef d’état-major de l’armée de Terre"],["COMCYBER","Commandement de la cyberdéfense"],["SICS","Système d’information du combat SCORPION"],["ATLAS","Automatisation des tirs et des liaisons d’artillerie sol-sol"],["MARTHA","Maillage de radars tactiques pour la lutte contre les hélicoptères et les aéronefs à voilure fixe"],["SAER","Solution d’aide à l’exploitation du renseignement"],["GESTER","Gestion de l’espace terrestre (ancien nom du LSM)"],["NEB","Numérisation de l’espace de bataille"],["PC TAC","Poste de commandement tactique"],["ECH","Échelon"],["PAC","Perception, attitude, comportement (cycle des effets de la déception)"],["SITACREF","Situation tactique de référence (autre appellation de la STR)"],["KLE","Key leader engagement – engagement des responsables clés"],["LAS","Ligne avant et de soutien (limite des tirs d’artillerie de l’unité qui recueille)"]);
